import { defineSchema, lazySchema } from "../../schemas/index.js";
export const getCacheBackendTypeSchema = defineSchema((v) => v.enum(["memory", "redis", "api", "disk"]));
export const getCacheSetBatchEntrySchema = defineSchema((v) => v.object({
    key: v.string(),
    value: v.string(),
    ttl: v.number().int().positive().optional(),
}));
// Backward compat aliases
export const CacheBackendTypeSchema = lazySchema(getCacheBackendTypeSchema);
export const CacheSetBatchEntrySchema = lazySchema(getCacheSetBatchEntrySchema);
